import{_ as d,a0 as a,w as c,s as l,I as n,x as o,a1 as t,A as p,ao as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"一些重要 Docker 命令的简单介绍 | LCTT x X-CMD","titleTemplate":false,"description":"一些重要 Docker 命令的简单介绍 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一些重要 Docker 命令的简单介绍 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一些重要 Docker 命令的简单介绍 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150413 A Walk Through Some Important Docker Commands","title":"一些重要 Docker 命令的简单介绍","tag":"201505","desc":""},"relativePath":"201505/20150413 A Walk Through Some Important Docker Commands.md","filePath":"[post].md"}'),s={name:"201505/20150413 A Walk Through Some Important Docker Commands.md"};function k(m,e,h,u,g,D){const r=a("Link");return c(),l("div",null,[e[16]||(e[16]=n("h1",{id:"一些重要-docker-命令的简单介绍",tabindex:"-1"},[o("一些重要 Docker 命令的简单介绍 "),n("a",{class:"header-anchor",href:"#一些重要-docker-命令的简单介绍","aria-label":"Permalink to “一些重要 Docker 命令的简单介绍”"},"​")],-1)),n("p",null,[e[1]||(e[1]=o("大家好，今天我们来学习一些在你使用 Docker 之前需要了解的重要的 Docker 命令。",-1)),t(r,{href:"https://www.docker.com/"},{default:p(()=>[...e[0]||(e[0]=[o("Docker",-1)])]),_:1}),e[2]||(e[2]=o(" 是一个开源项目，提供了一个可以打包、装载和运行任何应用的轻量级容器的开放平台。它没有语言支持、框架和打包系统的限制，从小型的家用电脑到高端服务器，在何时何地都可以运行。这使它们可以不依赖于特定软件栈和供应商，像一块块积木一样部署和扩展网络应用、数据库和后端服务。",-1))]),e[17]||(e[17]=i(`<p>Docker 命令简单易学，也很容易实现或实践。这是一些你运行 Docker 并充分利用它需要知道的简单 Docker 命令。</p><h3 id="_1-拉取-docker-镜像" tabindex="-1">1. 拉取 Docker 镜像 <a class="header-anchor" href="#_1-拉取-docker-镜像" aria-label="Permalink to “1. 拉取 Docker 镜像”">​</a></h3><p>由于容器是由 Docker 镜像构建的，首先我们需要拉取一个 docker 镜像来开始。我们可以从 Docker Registry Hub 获取所需的 docker 镜像。在我们使用 pull 命令拉取任何镜像之前，为了避免 pull 命令的一些恶意风险，我们需要保护我们的系统。为了保护我们的系统不受这个风险影响，我们需要添加 <strong>127.0.0.1 index.docker.io</strong> 到 /etc/hosts 条目。我们可以通过使用喜欢的文本编辑器完成。</p><pre><code># nano /etc/hosts
</code></pre><p>现在，增加下面的一行到文件并保存退出。</p><pre><code>127.0.0.1 index.docker.io
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/docker-hosts.png" alt="Docker 宿主机"></p><p>要拉取一个 docker 镜像，我们需要运行下面的命令。</p><pre><code># docker pull registry.hub.docker.com/busybox
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/pulling-image.png" alt="Docker pull 命令"></p><p>我们可以检查本地是否有可用的 Docker 镜像。</p><pre><code># docker images
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/docker-images.png" alt="Docker 镜像"></p><h3 id="_2-运行-docker-容器" tabindex="-1">2. 运行 Docker 容器 <a class="header-anchor" href="#_2-运行-docker-容器" aria-label="Permalink to “2. 运行 Docker 容器”">​</a></h3><p>现在，成功地拉取要求的或所需的 Docker 镜像之后，我们当然想运行这个 Docker 镜像。我们可以用 docker run 命令在镜像上运行一个 docker 容器。在 Docker 镜像上运行一个 docker 容器时我们有很多选项和标记。我们使用 -t 和 -i 选项来运行一个 docker 镜像并进入容器，如下面所示。</p><pre><code># docker run -it busybox
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/docker-run-shell.png" alt="Docker Run Shell 命令"></p><p>从上面的命令中，我们进入了容器并可以通过交互 shell 访问它的内容。我们可以键入 <strong>Ctrl-D</strong> 从shell中退出。</p><p>现在，在后台运行容器，我们用 -d 标记分离 shell，如下所示。</p><pre><code># docker run -itd busybox
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/run-container-background.png" alt="后台运行容器"></p><p>如果你想进入到一个正在运行的容器，我们可以使用 attach 命令加一个容器 id。可以使用 <strong>docker ps</strong> 命令获取容器 id。</p><pre><code># docker attach &lt;container id&gt;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/docker-attach.png" alt="进入Docker"></p><h3 id="_3-检查容器运行" tabindex="-1">3. 检查容器运行 <a class="header-anchor" href="#_3-检查容器运行" aria-label="Permalink to “3. 检查容器运行”">​</a></h3><p>不论容器是否运行，查看日志文件都很简单。我们可以使用下面的命令去检查是否有 docker 容器在实时运行。</p><pre><code># docker ps
</code></pre><p>现在，查看正在运行的或者之前运行的容器的日志，我们需要运行以下的命令。</p><pre><code># docker ps -a
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/view-docker-containers1.png" alt="查看 Docker 容器"></p><h3 id="_4-查看容器信息" tabindex="-1">4. 查看容器信息 <a class="header-anchor" href="#_4-查看容器信息" aria-label="Permalink to “4. 查看容器信息”">​</a></h3><p>我们可以使用 inspect 命令查看一个 Docker 容器的各种信息。</p><pre><code># docker inspect &lt;container id&gt;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/docker-inspect.png" alt="检查Docker"></p><h3 id="_5-杀死或删除" tabindex="-1">5. 杀死或删除 <a class="header-anchor" href="#_5-杀死或删除" aria-label="Permalink to “5. 杀死或删除”">​</a></h3><p>我们可以使用容器 id 杀死或者停止 docker 容器（进程），如下所示。</p><pre><code># docker stop &lt;container id&gt;
</code></pre><p>要停止每个正在运行的容器，我们需要运行下面的命令。</p><pre><code># docker kill $(docker ps -q)
</code></pre><p>现在，如我我们希望移除一个 docker 镜像，运行下面的命令。</p><pre><code># docker rm &lt;container id&gt;
</code></pre><p>如果我们想一次性移除所有 docker 镜像，我们可以运行以下命令。</p><pre><code># docker rm $(docker ps -aq)
</code></pre><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>这些都是充分学习和使用 Docker 很基本的 docker 命令。有了这些命令，Docker 变得很简单，可以提供给最终用户一个易用的计算平台。根据上面的教程，任何人学习 Docker 命令都非常简单。如果你有任何问题，建议，反馈，请写到下面的评论框中以便我们改进和更新内容。多谢！ 希望你喜欢 😃</p><hr>`,46)),n("p",null,[e[4]||(e[4]=o("via: ",-1)),t(r,{href:"http://linoxide.com/linux-how-to/important-docker-commands/"},{default:p(()=>[...e[3]||(e[3]=[o("http://linoxide.com/linux-how-to/important-docker-commands/",-1)])]),_:1})]),n("p",null,[e[8]||(e[8]=o("作者：",-1)),t(r,{href:"http://linoxide.com/author/arunp/"},{default:p(()=>[...e[5]||(e[5]=[o("Arun Pyasi",-1)])]),_:1}),e[9]||(e[9]=o(" 译者：",-1)),t(r,{href:"https://github.com/ictlyh"},{default:p(()=>[...e[6]||(e[6]=[o("ictlyh",-1)])]),_:1}),e[10]||(e[10]=o(" 校对：",-1)),t(r,{href:"https://github.com/wxy"},{default:p(()=>[...e[7]||(e[7]=[o("wxy",-1)])]),_:1})]),n("p",null,[e[13]||(e[13]=o("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[11]||(e[11]=[o("LCTT",-1)])]),_:1}),e[14]||(e[14]=o(" 原创翻译，",-1)),t(r,{href:"http://linux.cn/"},{default:p(()=>[...e[12]||(e[12]=[o("Linux中国",-1)])]),_:1}),e[15]||(e[15]=o(" 荣誉推出",-1))])])}const T=d(s,[["render",k]]);export{f as __pageData,T as default};
